const escapeHtml = value => String(value).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
function importResultHtml(){ if(!importOutcome)return '<p class="muted">Choose a file to see its name and validation result before replacing the saved set.</p>'; const o=importOutcome,v=o.validation; let html='<div class="card" style="margin-top:18px"><h3>Selected file: '+escapeHtml(o.filename)+'</h3>'; if(o.error)html+='<div class="notice">'+escapeHtml(o.error)+'</div>'; else {html+='<div class="validation-item">'+status(v.valid?'PASS':'UNRESOLVED')+' '+(v.valid?'Validation passed':'Validation failed')+' · '+v.count+'/100 records</div>'; if(v.dup.length)html+='<div class="validation-item">Duplicate IDs: '+escapeHtml(v.dup.join(', '))+'</div>'; if(v.unmapped.length)html+='<div class="validation-item">Missing, extra or unanswered IDs: '+escapeHtml(v.unmapped.join(', '))+'</div>'; if(v.schemaErrors.length)html+='<div class="validation-item">Required field errors: '+escapeHtml(v.schemaErrors.slice(0,12).join('; '))+(v.schemaErrors.length>12?' … and '+(v.schemaErrors.length-12)+' more':'')+'</div>'; if(v.valid&&!o.applied)html+='<button id="apply-import" class="button">Use this validated file</button>'; } html+='<p class="muted">'+(o.applied?'Saved dataset replaced after validation.':pendingImport?'Current saved dataset is unchanged until you use this file.':'Current saved dataset was preserved.')+'</p></div>'; return html; }
