const bs = [['Cash',60000],['Trade receivables, net of R-17 impairment',168000],['Saleable inventory',121000],['PPE, net',191000],['Total assets',540000],['Supplier payables',126000],['Closing payroll payable',32000],['Bank loan principal',131000],['Accrued interest',2000],['Customer deposits / contract liabilities',90000],['Employee claim provision',25000],['Damaged-stock disposal provision',0],['Total liabilities',406000],['Residual equity',134000],['Total liabilities and equity',540000]];
const cashflow = [['Opening cash',80000],['Customer receipts, including September deposits',899000],['Payroll cash paid',-231000],['Overhead and repairs paid',-141000],['Interest cash paid',-10000],['Supplier payments — bank confirmed',-378000],['Net operating cash flow',139000],['Capital expenditure',-80000],['Loan advance less principal repayment',31000],['Owner/personal withdrawals',-110000],['Net decrease in cash',-20000],['Closing cash',60000]];
const checks = [['Balance sheet balances','PASS','€540,000 assets = €406,000 liabilities + €134,000 equity'],['Closing cash agrees','PASS','Cash-flow roll-forward gives €60,000'],['Revenue to receivables','PASS with caveat','€960,000 − €774,000 = €186,000 gross; CRM WEB-NCB €53,000 open points to R-17. Less €18,000 impairment = €168,000 net; confirm subledger match.'],['Inventory to COGS','PASS WITH FOLLOW-UP','Selected count basis: €80,000 + €459,000 − €396,000 = €143,000 gross; less €22,000 damage = €121,000 net. Record the €9,000 favorable count-to-movement adjustment; investigate its root cause.'],['PPE reconciliation','PASS mechanically','€260,000 gross less €69,000 accumulated depreciation = €191,000'],['Debt and interest','PASS','€100,000 + €50,000 − €19,000 = €131,000 principal; €12,000 − €10,000 = €2,000 interest'],['Operating payment allocation','PASS','Bank confirms €378,000 supplier payments; with €231,000 payroll, €141,000 overhead/repairs and €10,000 interest, €760,000 is allocated.'],['Opening supplier payable','WARN','€45,000 inferred opening AP + €459,000 purchases − €378,000 bank payments = €126,000 closing AP; verify opening ledger.'],['Equity roll-forward','PASS algebraically','Common opening control €170,000 + selected count-basis PBT €74,000 − withdrawals €110,000 = €134,000; unadjusted movement sensitivity PBT €65,000 gives €125,000']];
const money = n => '€' + Math.abs(n).toLocaleString('en-US') + (n<0?'':'');
const status = s => `<span class="status ${s.includes('UNRESOLVED')?'unresolved':s.includes('WARN')||s.includes('caveat')||s.includes('REQUIRED')?'warn':'pass'}">${s}</span>`;
const approvedCount = () => approvedIds.size;
const canReview = () => dataset.imported || dataset.reviewable === true;
const isUnresolved = d => !d || !['resolved','resolved_with_evidence_gap'].includes(d.answerStatus);
const hasSourceGap = d => d.sourceDetailAvailable === false;
const studentNameConfirmed = () => importMeta?.data?.student?.name === student.name;
const nonEmpty = value => typeof value === 'string' && value.trim().length > 0;
const hasFirstProposal = d => ['verified_original','fresh_primary_ai_proposal_complete'].includes(d.firstProposalStatus) && nonEmpty(d.aiProposal);
const hasIndependentChallenge = d => String(d.independentChallengeStatus||'').startsWith('complete') && nonEmpty(d.independentChallenge);
const verifiedChallengeCount = () => (publishedSubmission?.decisions||dataset.decisions).filter(d=>d.reviewTier==='material_judgment'&&hasFirstProposal(d)&&hasIndependentChallenge(d)).length;

const verifiedFirstProposalCount = () => (publishedSubmission?.decisions||dataset.decisions).filter(d=>d.reviewTier==='material_judgment'&&hasFirstProposal(d)).length;
const localCertification = () => importMeta?.data?.studentCertification?.approved === true ? importMeta.data.studentCertification : null;
const certificationDate = record => new Date(record.certifiedAt).toLocaleString('en-GB',{dateStyle:'long',timeStyle:'short',timeZone:'Europe/Riga'});
const isPublishedCertified = obj => obj?.studentCertification?.approved === true && obj.studentCertification.status === 'certified_locally_by_student' && obj.studentCertification.student?.name === student.name && Array.isArray(obj.decisions) && obj.decisions.length === 100 && obj.decisions.every(d=>d.studentApproval?.approved === true) && obj.decisions.filter(d=>d.reviewTier==='material_judgment'&&hasFirstProposal(d)&&hasIndependentChallenge(d)).length === 25 && validate(obj).valid;
const reviewSignature = d => JSON.stringify([d.id,d.question,d.answer,d.finalAnswer,d.aiProposal,d.independentChallenge,d.statementEffect,d.evidence]);
function persistReviews(){ const marks={decisions:{},challenges:{}}; dataset.decisions.forEach(d=>{if(approvedIds.has(d.id))marks.decisions[d.id]=reviewSignature(d);if(checkedChallenges.has(d.id))marks.challenges[d.id]=reviewSignature(d)}); localStorage.setItem(REVIEW_KEY,JSON.stringify(marks)); }
function restoreReviews(){ approvedIds.clear(); checkedChallenges.clear(); let marks={}; try{marks=JSON.parse(localStorage.getItem(REVIEW_KEY)||'{}')||{}}catch(e){} dataset.decisions.forEach(d=>{const signature=reviewSignature(d);if(marks.decisions?.[d.id]===signature)approvedIds.add(d.id);if(marks.challenges?.[d.id]===signature&&hasFirstProposal(d)&&hasIndependentChallenge(d))checkedChallenges.add(d.id)}); persistReviews(); }
const certificationReady = () => dataset.imported && importMeta?.validation?.valid === true && studentNameConfirmed() && approvedCount() === 100 && checkedChallenges.size === 25 && verifiedChallengeCount() === 25 && !dataset.decisions.some(isUnresolved);
function updateSourceStatus(){ const el=document.querySelector('#source-status'); if(!el)return; el.textContent=publishedCertification?'● Student-certified submission published':REVIEW_MODE?'● Bundled preliminary submission':dataset.imported?'● Validated JSON imported':'● Bundled preliminary JSON'; }
function hydrateImportedData(){ try{ const saved=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null'); if(saved&&Array.isArray(saved.decisions)){ const validation=validate(saved.data||{decisions:saved.decisions}); if(validation.valid){ dataset={decisions:saved.decisions,imported:true,reviewable:true,source:saved.filename||'saved JSON'}; importMeta={...saved,validation}; restoreReviews(); return true; } } }catch(e){} return false; }
function saveImportedData(obj,filename,validation){ const saved={data:obj,decisions:obj.decisions,filename,importedAt:new Date().toISOString(),validation}; persistReviews(); localStorage.setItem(STORAGE_KEY,JSON.stringify(saved)); importMeta=saved; dataset={decisions:obj.decisions,imported:true,reviewable:true,source:filename}; restoreReviews(); updateSourceStatus(); }
function clearImportedData(){ localStorage.removeItem(STORAGE_KEY); localStorage.removeItem(REVIEW_KEY); importMeta=null; approvedIds.clear(); checkedChallenges.clear(); dataset={decisions:[],imported:false,reviewable:false,source:'bundled preliminary JSON'}; updateSourceStatus(); showToast('Saved imported data cleared'); setPage('import'); }
const metric = (label,value,note) => `<div class="metric"><div class="metric-label">${label}</div><div class="metric-value">${value}</div><div class="metric-note">${note}</div></div>`;
const table = (headers, rows) => `<div class="card table-card"><div class="table-wrap"><table class="data-table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`;
function setPage(p){ currentPage=p; document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===p)); pageTitle.textContent = REVIEW_MODE&&p==='overview'?'Review overview':({overview:'Overview',decisions:'Decision Register',judgments:'Material Judgments',statements:'Financial Statements',schedules:'Supporting Schedules',assumptions:'Key Assumptions',evidence:'Evidence & Reliability',trail:'AI Review Trail',uncertainties:'Uncertainties & Board Recommendation',certification:'Student Certification',import:'Import data'})[p]||'Overview'; render(p); window.scrollTo(0,0); }
function render(p){
 if(REVIEW_MODE && p==='overview') return assessorReview();
 if(p==='overview') return overview(); if(p==='decisions') return decisions(); if(p==='judgments') return judgments(); if(p==='statements') return statements(); if(p==='schedules') return schedules(); if(p==='assumptions') return assumptions(); if(p==='evidence') return evidence(); if(p==='trail') return trail(); if(p==='uncertainties') return uncertaintyPage(); if(p==='certification') return certification(); if(p==='import') return importPage(); overview();
}
function assessorReview(){ const rows=decisionRows(); const low=rows.filter(d=>d.confidence==='low').length; const unresolved=rows.filter(isUnresolved).length; const sourceGaps=rows.filter(hasSourceGap).length; const changed=rows.filter(d=>d.changedFromAI===true).length; app.innerHTML=`<div class="hero"><div><h2>Compact assessor review</h2><p>Read-only view of the ${publishedCertification?'student-certified':'preliminary'} submission. Original positions and revised answers remain visible.</p></div>${status(unresolved?'UNRESOLVED':publishedCertification?'PASS':'WARN')} ${unresolved?unresolved+' unanswered decisions':sourceGaps+' source-detail gaps; '+(publishedCertification?'student certification recorded':'student certification required')}</div><div class="metrics">${metric('Decision records',rows.length,'D001–D100')}${metric('Material judgments',rows.filter(d=>d.reviewTier==='material').length,'25 judgments')}${metric('Independent analyses received',verifiedChallengeCount()+' / 25','fresh second-agent review')}${metric('Low confidence',low,'requires attention')}${metric('Source-detail gaps',sourceGaps,'answered with limitations')}${metric('Differences from earlier draft',changed,'historical Agent 1 matrix unavailable')}${metric('Open uncertainties',summary.open,'see uncertainties page')}</div><div class="grid-2"><div class="card"><div class="card-head"><div><h3>Assessor checks</h3><p class="card-sub">Key controls before relying on the submission</p></div></div>${[['All D IDs present',rows.length===100?'PASS':'UNRESOLVED','D001 through D100 are present exactly once.'],['Independent challenges recorded',verifiedChallengeCount()===25?'PASS':'WARN','Fresh primary-AI first proposals and independent second-agent analyses are recorded for all 25 decisions.'],['First proposal matrix',verifiedFirstProposalCount()===25?'PASS':'REQUIRED','Fresh primary-AI proposals are complete; they are not represented as a historical Agent 1 transcript.'],['Student certification',publishedCertification?'PASS':'REQUIRED',publishedCertification?'The student personally certified the published submission on '+certificationDate(publishedCertification)+'.':'The AI does not certify the final decisions.'],['COGS / inventory','WARN','Recommended count basis: €396,000 consumption and €121,000 net stock; recognize and disclose the €9,000 count-to-movement adjustment. Investigate the cause before valuation or earn-out use.'],['Receivables / R-17','WARN','CRM points to R-17; exact €18,000 subledger match remains open.']].map(c=>`<div class="check-row"><div>${c[0]}</div><div>${status(c[1])}</div><div class="comment">${c[2]}</div></div>`).join('')}</div><div class="card"><h3>Submission links</h3><div class="list-row"><strong>Full submission JSON</strong><a href="/submission.json" download>Download JSON</a></div><div class="list-row"><strong>Column I values</strong><a href="/column_I_values.csv" download>Download 100-row CSV</a></div><div class="list-row"><strong>Decision Register</strong><span>100 records</span></div><div class="list-row"><strong>Student</strong><span>${student.name} · ${student.id}</span></div><div class="notice" style="margin-top:16px">Use the navigation to inspect low-confidence decisions and source gaps. Primary source files were reviewed locally and are kept outside this public project.</div></div></div><h3 class="section-title">Decision attention list</h3><div class="card">${rows.filter(d=>d.confidence==='low'||isUnresolved(d)||d.changedFromAI===true).slice(0,20).map(d=>`<div class="list-row"><strong><span class="id">${d.id}</span> ${d.title||d.question}</strong><span>${status(isUnresolved(d)?'UNRESOLVED':d.confidence==='low'?'WARN':'PASS')}</span></div>`).join('')||'<div class="empty">No flagged records.</div>'}</div>`; }
function overview(){ app.innerHTML=`<div class="hero"><div><h2>Reconciliation workspace</h2><p>${publishedCertification?'Student-certified answer set with disclosed evidence gaps.':'Preliminary answer set with visible source gaps. Import a validated JSON to begin personal approval.'}</p></div><div class="hero-aside">${status(publishedCertification?'PASS':'WARN')} ${publishedCertification?'Student-certified final':'Not yet certified'}</div></div><div class="metrics">${metric('Profit before tax',money(summary.pbt),'proposed')}${metric('Closing cash',money(summary.cash),'arithmetic roll-forward')}${metric('Total assets',money(summary.assets),'balance sheet')}${metric('Residual equity',money(summary.equity),'after liabilities')}${metric('Open uncertainties',summary.open,'require student attention')}</div><div class="card" style="margin-bottom:20px"><div class="card-head"><div><h3>Board decision brief</h3><p class="card-sub">Working conclusion for 31 August 2026</p></div>${status(publishedCertification?'PASS':'WARN')} ${publishedCertification?'Student-certified; caveats disclosed':'Provisional'}</div><div class="list-row"><strong>Use the reconciled figures for internal review</strong><span>Selected working PBT €74,000 on physical-count basis; disclosed €9,000 count adjustment</span></div><div class="list-row"><strong>Protect cash and pause valuation decisions</strong><span>Bank cash €60,000; do not use management’s unsupported €312,000 profit for an earn-out</span></div><div class="list-row"><strong>Outstanding evidence follow-up</strong><span>€9,000 count-to-movement adjustment follow-up, inferred €45,000 opening AP, owner-payment form, 11 source-detail gaps</span></div><p class="muted" style="margin-top:14px">This brief is a board recommendation, not student certification. The three statements and source locators remain available in the sections below.</p></div><div class="grid-2"><div class="card"><div class="card-head"><div><h3>Control checks</h3><p class="card-sub">Arithmetic controls and remaining source conflicts</p></div><span class="tag">${checks.filter(x=>x[1].startsWith('PASS')).length} of ${checks.length} pass</span></div>${checks.map(c=>`<div class="check-row"><div>${c[0]}</div><div>${status(c[1])}</div><div class="comment">${c[2]}</div></div>`).join('')}</div><div class="card"><div class="card-head"><div><h3>Review progress</h3><p class="card-sub">${publishedCertification?'Published student certification is recorded':'Student decisions are intentionally unapproved'}</p></div></div><div class="list-row"><strong>Operational decisions</strong><span>${publishedCertification?75:dataset.decisions.filter(d=>d.reviewTier==='operational'&&!isUnresolved(d)).length} / 75 answered</span></div><div class="list-row"><strong>Material judgments</strong><span>${publishedCertification?25:dataset.decisions.filter(d=>d.reviewTier==='material_judgment'&&!isUnresolved(d)).length} / 25 answered</span></div><div class="list-row"><strong>Independent second-agent analyses received</strong><span>${publishedCertification?25:verifiedChallengeCount()} / 25</span></div><div class="list-row"><strong>Complete first proposals verified</strong><span>${publishedCertification?25:verifiedFirstProposalCount()} / 25</span></div><div class="list-row"><strong>${publishedCertification?'Published decisions approved':'Required decisions approved'}</strong><span>${publishedCertification?100:approvedCount()} / 100</span></div><div class="list-row"><strong>JSON source</strong><span>${dataset.imported?'Validated import':'Bundled preliminary JSON'}</span></div><div class="mini-bar"><span style="width:${publishedCertification?'100':'0'}%"></span></div><div class="notice" style="margin-top:16px">All 100 answers state a treatment. Eleven lack separate source detail; fresh first proposals and independent second-agent analyses are recorded for all 25; ${publishedCertification?'The student-certified submission is available for download; source-detail gaps remain disclosed.':'Personal review and certification remain pending.'}</div></div></div><h3 class="section-title">Open uncertainties</h3><div class="card"><div class="two-col-list">${uncertainties.map(u=>`<div class="list-row"><strong>${u[0]}</strong><span>${u[1]}</span></div>`).join('')}</div></div>`; }
function decisionRows(){ const source=publishedSubmission?.decisions||dataset.decisions; const list=source.length?source:Array.from({length:100},(_,i)=>({id:i<75?`O-${String(i+1).padStart(3,'0')}`:`M-${String(i-74).padStart(3,'0')}`,reviewTier:i<75?'operational':'material',question:i<75?'Operational decision awaiting imported record':'Material judgment awaiting imported record',answer:'Preview placeholder — import JSON to populate',confidence:'—',evidence:[],mappingStatus:'preview'})); return list.map(d=>({...d, reviewTier:d.reviewTier==='material_judgment'?'material':d.reviewTier})); }
function bindApprovalBoxes(){ document.querySelectorAll('.approve-box').forEach(box=>box.addEventListener('change',e=>{ const id=e.target.dataset.id; if(e.target.checked) approvedIds.add(id); else approvedIds.delete(id); persistReviews(); document.querySelectorAll('.approved-count').forEach(el=>el.textContent=`${approvedCount()} / 100 approved`); showToast(e.target.checked?`${id} marked reviewed`:`${id} review removed`); })); }
function decisions(){ const rows=decisionRows(); app.innerHTML=`<div class="hero"><div><h2>Decision Register</h2><p>Review each record and tick the student approval box only after checking evidence, reasoning and caveats.</p></div><div class="hero-aside">${status('WARN')} <span class="approved-count">${publishedCertification?100:approvedCount()} / 100 approved</span></div></div><div class="filters"><input id="decision-search" placeholder="Search ID, question or evidence"/><select id="tier"><option value="all">All decision types</option><option value="operational">Operational</option><option value="material">Material</option></select><select id="confidence"><option value="all">All confidence</option><option>high</option><option>medium-high</option><option>medium</option><option>low</option></select><select id="mapping"><option value="all">All mapping states</option><option value="gap">Source-detail gap</option><option value="resolved">Answered</option></select></div><div id="decision-table">${decisionTable(rows)}</div>`; document.querySelectorAll('.filters select,#decision-search').forEach(el=>el.addEventListener('input',filterDecisions)); bindApprovalBoxes(); }
function decisionTable(rows){ return `<div class="toolbar"><span class="count">Showing ${rows.length} of 100 records</span><span class="muted">Tick Student approval after review</span></div>`+table(['Student approval / ID','Type','First proposal record','Fresh second-agent analysis','Recommended final answer','Review explanation','Evidence / reliability','Confidence','Source detail','Impact'],rows.map(d=>[`<label style="display:flex;gap:7px;align-items:flex-start"><input class="approve-box" type="checkbox" data-id="${d.id}" ${publishedCertification||approvedIds.has(d.id)?'checked':''} ${publishedCertification||!canReview()?'disabled':''}/><span class="id">${d.id}</span></label>`, `<span class="tag">${d.reviewTier||'—'}</span>`, d.agent1Position||d.agent1||d.question||'Not separately stated', d.agent2Position||d.agent2||'Not separately stated', d.finalAnswer||d.answer||'Awaiting review', d.reviewExplanation||d.studentReasoning||'Awaiting review', (d.evidence||[]).slice(0,2).join('<br/>')||'Preview placeholder', d.confidence||'—', hasSourceGap(d)?(d.sourceGap?.display||'Separate amount not supported'):'See cited source', d.financialStatementImpact||'See reasoning'])); }
function filterDecisions(){ const q=(document.querySelector('#decision-search').value||'').toLowerCase(), tier=document.querySelector('#tier').value, conf=document.querySelector('#confidence').value, map=document.querySelector('#mapping').value; let rows=decisionRows().filter(d=>(tier==='all'||d.reviewTier===tier)&&(conf==='all'||d.confidence===conf)&&(map==='all'||(map==='gap'?hasSourceGap(d):!isUnresolved(d)))&&JSON.stringify(d).toLowerCase().includes(q)); document.querySelector('#decision-table').innerHTML=decisionTable(rows); bindApprovalBoxes(); }
function judgmentStatus(d){ if(isUnresolved(d)) return 'UNRESOLVED'; if(!hasIndependentChallenge(d)||!hasFirstProposal(d)) return 'REQUIRED'; if(d.confidence==='low'||hasSourceGap(d)||d.confidence==='medium') return 'WARN'; return 'PASS'; }
function judgments(){ const rows=decisionRows().filter(d=>d.reviewTier==='material'); app.innerHTML=`<div class="hero"><div><h2>Material Judgments</h2><p>25 higher-risk accounting judgments. Available first proposals: ${verifiedFirstProposalCount()}/25; complete independent analyses: ${verifiedChallengeCount()}/25. Fresh proposals are identified by provenance; ${publishedCertification?'the published submission records student review.':'personal review remains pending.'}</p></div><span class="tag">25 records</span></div><div class="card">${rows.slice(0,25).map((d,i)=>`<details class="accordion"><summary><span><span class="id">${d.id}</span> &nbsp; ${d.question||'Material judgment'}</span><span>${status(judgmentStatus(d))}</span></summary><div class="accordion-body"><div class="two-col-list"><div><b>First AI proposal</b><br/>${d.aiProposal||'Proposal not supplied.'}<p class="muted">${d.firstProposalProvenance||'Provenance not recorded.'}</p></div><div><b>Independent challenge</b><br/>${d.independentChallenge||'Independent analysis not supplied.'}<p class="muted">Source labels: ${(d.evidence||[]).join('; ')||'Not supplied'}</p></div><div><b>${publishedCertification?'AI-assisted reasoning adopted in the certified submission':'AI draft reasoning — student review pending'}</b><br/>${d.reasoning||d.studentReasoning||d.answer||'Awaiting student review.'}</div><div><b>Comparison and final choice</b><br/>${d.challengeComparison||'Comparison not supplied.'}<p>${d.finalAnswer||d.answer||'Awaiting final choice.'}</p></div><div><b>Financial statement impact</b><br/>${d.financialStatementImpact||'Awaiting mapped impact.'}<p class="muted">Profit ${d.statementEffect?.profit??'—'} · Cash ${d.statementEffect?.cash??'—'} · Other assets ${d.statementEffect?.assets??'—'} · Liabilities ${d.statementEffect?.liabilities??'—'} · Equity ${d.statementEffect?.equity??'—'}</p></div></div><label class="cert-check"><input class="challenge-box" type="checkbox" data-id="${d.id}" ${publishedCertification||checkedChallenges.has(d.id)?'checked':''} ${publishedCertification||!canReview()||!hasFirstProposal(d)||!hasIndependentChallenge(d)?'disabled':''}/> ${publishedCertification?'Student review recorded in the published submission.':'I personally reviewed this first proposal and independent analysis.'}</label></div></details>`).join('')}</div>`; document.querySelectorAll('.challenge-box').forEach(box=>box.addEventListener('change',e=>{const id=e.target.dataset.id;if(e.target.checked)checkedChallenges.add(id);else checkedChallenges.delete(id);persistReviews();showToast(id+(e.target.checked?' review marked':' review removed'));})); }
function statementCard(title, rows){ return `<div class="card"><div class="card-head"><div><h3>${title}</h3><p class="card-sub">EUR · proposed working presentation</p></div></div><table class="statement-table">${rows.map((r,i)=>`<tr class="${i===rows.length-1||r[0].startsWith('Total')||r[0].includes('profit')?'total':''}"><td>${r[0]}</td><td>${r[1].toLocaleString('en-US')}</td></tr>`).join('')}</table></div>`; }
function statements(){ app.innerHTML=`<div class="hero"><div><h2>Financial Statements</h2><p>Selected physical-count basis, with the €9,000 adjustment and disposal sensitivity shown.</p></div>${status('WARN')} Source evidence pending</div><div class="statement-grid">${statementCard('Profit & Loss',pnl)}${statementCard('Cash Flow',cashflow)}${statementCard('Balance Sheet',bs)}</div><h3 class="section-title">Reconciliation checks</h3><div class="grid-2"><div class="card">${checks.map(c=>`<div class="check-row"><div>${c[0]}</div><div>${status(c[1])}</div><div class="comment">${c[2]}</div></div>`).join('')}</div><div class="card"><h3>Unadjusted management movement sensitivity</h3><div class="notice" style="margin-top:14px">The management movement schedule states €405,000 consumption, which would imply €112,000 net stock and €65,000 PBT without adjustment. This is retained as a reconciliation sensitivity, not the selected working basis. The physical count supports €121,000 net stock and €74,000 PBT; the €9,000 adjustment and its root cause are disclosed for follow-up.</div><div class="notice" style="margin-top:12px">The €2,000 disposal quote is not accrued because a present obligation is not evidenced. If one is proven, selected PBT falls to €72,000, liabilities rise to €408,000 and equity falls to €132,000; the unadjusted movement sensitivity becomes €63,000 PBT, €408,000 liabilities and €123,000 equity.</div></div></div>`; }
function schedules(){ const groups=[['Revenue and receivables','NorthStar €180,000 + Freedom €200,000 + Phoenix €100,000 + Liberty €120,000 + Finally Single €270,000 + Never Call Back €90,000 = €960,000 revenue. Gross receivables €960,000 − €774,000 receipts against period sales = €186,000; less R-17 €18,000 = €168,000 net, with CRM WEB-NCB linking its €53,000 gross open balance to R-17; confirm the €18,000 customer match. September advances €60,000 + €30,000 = €90,000 liability.'],['Inventory and COGS','Selected count basis: opening €80,000 + purchases €459,000 − gross physical count €143,000 = €396,000 materials consumed; less €22,000 damage leaves €121,000 saleable stock. Recognize a disclosed €9,000 favorable count-to-movement adjustment versus the €405,000 management schedule. Investigate its root cause; do not use the unadjusted schedule as the selected basis.'],['Supplier payables','Received purchases: Box €130,000 + Glass €120,000 + Print €95,000 + Event €114,000 = €459,000. Bank payments: €105,000 + €92,000 + €81,000 + €100,000 = €378,000. Closing unpaid: €25,000 + €28,000 + €14,000 + €59,000 = €126,000. Inferred opening AP €45,000, all Event: €45,000 + €114,000 − €100,000 = €59,000; verify opening ledger.'],['Payroll','Opening payable €15,000 + expense €248,000 − cash paid €231,000 = €32,000 closing payable. Expense splits into event delivery €80,000, sales €72,000 and office/finance €96,000.'],['Operating expenses','Rent €48,000 + marketing €55,000 + software €16,000 + utilities €12,000 = €131,000; repairs add €10,000.'],['PPE and depreciation','Opening gross €180,000 + packaging machine €60,000 + photo booth €20,000 = €260,000 gross. Opening accumulated depreciation €45,000 + current €24,000 = €69,000; net €191,000.'],['Debt and interest','Opening principal €100,000 + €50,000 advance − €19,000 repayment = €131,000. Interest expense €12,000 − paid €10,000 = €2,000 accrued.'],['Cash-payment allocation','Customer receipts €774,000 on current-period sales + €35,000 opening receivable settlement + €90,000 September advances = €899,000. Operating payments: bank-confirmed suppliers €378,000 + payroll €231,000 + overhead/repairs €141,000 + interest €10,000 = €760,000.'],['Cash and equity','Cash: €80,000 opening + €139,000 operating − €80,000 equipment + €31,000 net borrowing − €110,000 owner payments = €60,000. Common opening equity control €170,000 + selected PBT €74,000 − €110,000 = €134,000; alternate PBT €65,000 gives €125,000.'],['Disposal provision','€2,000 quote supports the amount, but the supplied evidence does not show a present legal or constructive obligation at 31 August. No provision is recognised in the selected statements. If such an obligation is proven, PBT falls from €74,000 to €72,000.']]; app.innerHTML=`<div class="hero"><div><h2>Supporting Schedules</h2><p>Detailed bridges for the selected physical-count basis and the disclosed €9,000 adjustment.</p></div></div><div class="two-col-list">${groups.map(g=>`<div class="card" style="margin-bottom:18px"><h3>${g[0]}</h3><p class="card-sub" style="margin-top:9px;line-height:1.55">${g[1]}</p><div style="margin-top:15px">${status(g[0].includes('Inventory')||g[0].includes('Disposal')||g[0].includes('Supplier payables')?'WARN':'PASS')}</div></div>`).join('')}</div>`; }
