function certifiedPanel(record,isPublic){ const name=escapeHtml(record.student?.name||student.name), date=escapeHtml(certificationDate(record)); app.innerHTML=`<div class="hero"><div><h2>Student Certification</h2><p>The student's confirmation is recorded.</p></div>${status('PASS')} ${isPublic?'Published student-certified final':'Certified in this browser'}</div><div class="cert-box"><h3>${isPublic?'Published student certification':'Your certification was saved'}</h3><p><strong>${name}</strong> · ${date} (Riga time)</p><div class="list-row"><strong>Decisions personally approved</strong><span>100 / 100</span></div><div class="list-row"><strong>Material proposals and independent analyses reviewed</strong><span>25 / 25</span></div><div class="list-row"><strong>Source-detail gaps disclosed</strong><span>11</span></div><p>${escapeHtml(record.declaration||certificationDeclaration)}</p>${isPublic?'<a href="/submission.json" download>Download the published certified JSON</a>':'<button id="download-local-cert" class="button">Download certified JSON again</button>'}<p class="muted" style="margin-top:16px">The website publication records the student certification. Submission to an assessor remains a separate action.</p></div>`; if(!isPublic)document.querySelector('#download-local-cert')?.addEventListener('click',()=>downloadCertifiedObject(importMeta.data)); }
function certifyImportedData(){ if(!certificationReady()||!document.querySelector('#cert-confirm')?.checked)return; const obj=JSON.parse(JSON.stringify(importMeta.data||{decisions:dataset.decisions})); obj.decisions=obj.decisions.map(d=>({...d,studentApproval:{status:'approved',approved:true}})); obj.studentCertification={status:'certified_locally_by_student',approved:true,student:obj.student,declaration:certificationDeclaration,certifiedAt:new Date().toISOString()}; const blob=new Blob([JSON.stringify(obj,null,2)+'\n'],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a'); link.href=url; link.download='certified_submission.json'; link.click(); setTimeout(()=>URL.revokeObjectURL(url),1000); importMeta={...importMeta,data:obj,decisions:obj.decisions,certifiedAt:obj.studentCertification.certifiedAt}; localStorage.setItem(STORAGE_KEY,JSON.stringify(importMeta)); showToast('Certified JSON downloaded; external submission is separate'); setPage('certification'); }
function certification(){ const recorded=publishedCertification||localCertification(); if(recorded)return certifiedPanel(recorded,!!publishedCertification); const ready=certificationReady(),unresolved=dataset.decisions.filter(isUnresolved).length; const reasons=[]; if(!dataset.imported||importMeta?.validation?.valid!==true)reasons.push('Import a validated answer set.'); if(!studentNameConfirmed())reasons.push('Confirm the student name in the imported set.'); if(unresolved)reasons.push(unresolved+' decisions remain unanswered.'); if(verifiedFirstProposalCount()<25)reasons.push((25-verifiedFirstProposalCount())+' first proposals are missing or incomplete.'); if(verifiedChallengeCount()<25)reasons.push((25-verifiedChallengeCount())+' independent analyses are missing or incomplete.'); if(checkedChallenges.size<25)reasons.push((25-checkedChallenges.size)+' material reviews need a personal check.'); if(approvedCount()<100)reasons.push((100-approvedCount())+' decisions need a personal review mark.'); app.innerHTML=`<div class="hero"><div><h2>Student Certification</h2><p>Final decisions belong to the student reviewer. AI prepares and preserves the trail; it does not certify.</p></div>${status(ready?'PASS':'REQUIRED')} ${ready?'Ready for explicit confirmation':'Student action required'}</div><div class="cert-box"><h3>Certification gate</h3><p>Student reviewer: <strong>${importMeta?.data?.student?.name||student.name}</strong> · ID <strong>${student.id}</strong></p><p>Certification requires an imported, validated answer set, personal review of all 100 decisions, complete first proposals and independent challenges for all 25 material judgments, review of the 11 source-detail gaps, and a confirmed student name.</p><div class="list-row"><strong>Required decisions reviewed</strong><span class="approved-count">${approvedCount()} / 100 approved</span></div><div class="list-row"><strong>Imported student name matches confirmed identity</strong><span>${status(studentNameConfirmed()?'PASS':'REQUIRED')}</span></div><div class="list-row"><strong>Unanswered decisions</strong><span class="${unresolved?'unresolved':'pass'}">${unresolved} remaining</span></div><div class="list-row"><strong>Source-detail gaps requiring review</strong><span>${decisionRows().filter(hasSourceGap).length}</span></div><div class="list-row"><strong>Complete first proposals and independent analyses</strong><span>${verifiedChallengeCount()} / 25</span></div><div class="list-row"><strong>Personally checked material reviews</strong><span>${checkedChallenges.size} / 25</span></div><button id="mark-all" class="button ghost" ${canReview()&&verifiedChallengeCount()===25?'':'disabled'}>Отметить все проверенными</button><div class="notice" style="margin-top:14px"><strong>Certification requirements:</strong> ${reasons.length?reasons.map(escapeHtml).join(' '):'All review gates met. Final declaration still requires your separate confirmation.'}</div><label class="cert-check"><input id="cert-confirm" type="checkbox" ${ready?'':'disabled'}/> ${certificationDeclaration}</label><button id="certify-btn" class="button" disabled>Certify and download JSON</button><p class="muted" style="margin-top:16px">This action downloads a locally certified JSON file. It does not upload or submit to an assessor.</p></div><h3 class="section-title">Before certification</h3><div class="card"><div class="check-row"><div>Import validated JSON answer set</div><div>${status(dataset.imported?'PASS':'REQUIRED')}</div><div class="comment">Import rejects missing IDs, duplicate IDs and unanswered decisions.</div></div><div class="check-row"><div>Answer all D001–D100 decisions</div><div>${status(unresolved?'UNRESOLVED':'PASS')}</div><div class="comment">${unresolved} unanswered records remain; 11 source-detail gaps remain documented.</div></div><div class="check-row"><div>Verify independent material challenges</div><div>${status(verifiedChallengeCount()===25?'PASS':'REQUIRED')}</div><div class="comment">Independent analyses received: ${verifiedChallengeCount()} of 25. Complete first proposals verified: ${verifiedFirstProposalCount()} of 25.</div></div><div class="check-row"><div>Review all decisions</div><div>${status(approvedCount()===100?'PASS':'REQUIRED')}</div><div class="comment">Review all 25 material judgments alongside the operational records.</div></div></div>`; const confirm=document.querySelector('#cert-confirm'), button=document.querySelector('#certify-btn'); if(confirm)confirm.addEventListener('change',()=>button.disabled=!confirm.checked); if(button)button.addEventListener('click',certifyImportedData); const markAll=document.querySelector('#mark-all'); if(markAll)markAll.addEventListener('click',()=>{if(!canReview()||verifiedChallengeCount()!==25)return; if(!window.confirm('Подтвердите, что вы лично просмотрели все 25 первых предложений и независимых разборов, а также 100 решений. Эти отметки не являются финальной сертификацией.'))return; dataset.decisions.forEach(d=>approvedIds.add(d.id)); dataset.decisions.filter(d=>d.reviewTier==='material_judgment'&&hasFirstProposal(d)&&hasIndependentChallenge(d)).forEach(d=>checkedChallenges.add(d.id)); persistReviews(); showToast('Manual review marks saved; final certification remains separate'); certification();}); }
function importPage(){ app.innerHTML=`<div class="hero"><div><h2>JSON Import</h2><p>Import a complete 100-decision JSON for personal review. The bundled answer set resolves all 100 treatments and flags 11 source-detail gaps.</p></div></div><div class="import-panel"><div class="dropzone" id="dropzone"><strong>Choose a JSON answer set</strong><span>Expected: a decisions array with 100 records and stable decision IDs.</span><br/><button class="button" style="margin-top:16px">Browse JSON file</button></div><p class="muted">Need the prepared answer set? <a href="DPI-HT-01_review_draft_for_import.json" download>Download the 100-decision draft JSON</a>.</p>${dataset.imported?`<div class="card" style="margin-top:18px"><h3>Saved imported data</h3><div class="list-row"><strong>Source file</strong><span>${importMeta?.filename||dataset.source}</span></div><div class="list-row"><strong>Imported at</strong><span>${importMeta?.importedAt||'Saved locally'}</span></div><div class="list-row"><strong>Validation</strong><span>${status('PASS')} 100/100 records; no duplicate or missing D IDs</span></div><button id="clear-import" class="button ghost">Clear imported data</button></div>`:''}<div class="validation"><h3>Validation rules</h3><div class="card"><div class="validation-item">${status('PASS')} Schema presence: <span class="muted">decisions array, record IDs, decision type, agent positions and mapping fields.</span></div><div class="validation-item">${status('WARN')} Completeness: <span class="muted">exactly 100 decision records expected: D001 through D100.</span></div><div class="validation-item">${status('WARN')} Uniqueness: <span class="muted">duplicate IDs are blocking errors.</span></div><div class="validation-item">${status('WARN')} Mapping: <span class="muted">missing or unanswered decision IDs block saving.</span></div><div class="validation-item">${status('WARN')} Evidence: <span class="muted">original evidence references and reliability levels are retained.</span></div></div><div id="import-result">${importResultHtml()}</div></div></div>`; document.querySelector('#dropzone').addEventListener('click',()=>document.querySelector('#json-file').click()); const clear=document.querySelector('#clear-import'); if(clear)clear.addEventListener('click',clearImportedData); const apply=document.querySelector('#apply-import'); if(apply)apply.addEventListener('click',()=>{if(!pendingImport)return; saveImportedData(pendingImport.data,pendingImport.filename,pendingImport.validation); importOutcome={filename:pendingImport.filename,validation:pendingImport.validation,applied:true}; pendingImport=null; showToast('Validated JSON imported and saved'); setPage('import');}); }
function validate(obj){
 const expected=Array.from({length:100},(_,i)=>'D'+String(i+1).padStart(3,'0'));
 const arr=Array.isArray(obj?.decisions)?obj.decisions:[];
 const ids=arr.map(d=>d?.id).filter(Boolean);
 const dup=[...new Set(ids.filter((id,i)=>ids.indexOf(id)!==i))];
 const missing=expected.filter(id=>!ids.includes(id));
 const extra=ids.filter(id=>!expected.includes(id));
 const schemaErrors=[];
 const object=x=>x!==null&&typeof x==='object'&&!Array.isArray(x);
 const requiredString=(value,label)=>{if(!nonEmpty(value))schemaErrors.push(label)};
 if(!object(obj))schemaErrors.push('Invalid JSON root');
 for(const k of ['schemaVersion','caseId','student','evidence','decisions','schedules','statements','reconciliations','uncertainties','boardRecommendation']) if(!Object.hasOwn(obj||{},k)) schemaErrors.push('Missing '+k);
 if(obj?.schemaVersion!=='1.0'||obj?.caseId!=='DPI-HT-01') schemaErrors.push('Wrong schemaVersion or caseId');
 if(!object(obj?.student)||!nonEmpty(obj.student.id)||!nonEmpty(obj.student.name)) schemaErrors.push('Invalid student');
 for(const k of ['evidence','decisions','reconciliations','uncertainties']) if(!Array.isArray(obj?.[k])) schemaErrors.push('Invalid '+k);
 for(const k of ['schedules','statements','boardRecommendation']) if(!object(obj?.[k])) schemaErrors.push('Invalid '+k);
 if(!['profitAndLoss','cashFlow','balanceSheet'].every(k=>Object.hasOwn(obj?.statements||{},k))) schemaErrors.push('Missing financial statement');
 if(object(obj?.schedules)&&Object.keys(obj.schedules).length===0) schemaErrors.push('Empty schedules');
 if(object(obj?.statements)&&!['profitAndLoss','cashFlow','balanceSheet'].every(k=>object(obj.statements[k])&&Object.keys(obj.statements[k]).length>0)) schemaErrors.push('Empty financial statement');
 if(object(obj?.boardRecommendation)&&(!nonEmpty(obj.boardRecommendation.recommendation)||!Array.isArray(obj.boardRecommendation.actions)||obj.boardRecommendation.actions.length!==5||!obj.boardRecommendation.actions.every(nonEmpty))) schemaErrors.push('Incomplete board recommendation');
 const effectKeys=['profit','cash','assets','liabilities','equity'];
 for(const d of arr){
  const id=d?.id||'(missing ID)';
  if(!object(d)||!/^D[0-9]{3}$/.test(id)||!nonEmpty(d.category)||!['operational','material_judgment'].includes(d.reviewTier)||!nonEmpty(d.question)||!Array.isArray(d.evidence)||!d.evidence.length||!d.evidence.every(nonEmpty)||!['low','medium','high'].includes(d.confidence)||d.templateDecisionId!==id) schemaErrors.push(id+': invalid required decision fields');
  requiredString(d?.answer,id+': missing answer');
  requiredString(d?.finalAnswer,id+': missing final answer');
  if(isUnresolved(d))schemaErrors.push(id+': unanswered status');
  if(d?.reviewTier==='material_judgment'){
   const e=d.statementEffect;
   if(!nonEmpty(d.aiProposal)||!nonEmpty(d.independentChallenge)||!nonEmpty(d.studentReasoning)||!object(e)||!effectKeys.every(k=>Object.hasOwn(e||{},k)&&(e[k]===null||typeof e[k]==='number'&&Number.isFinite(e[k])))||typeof d.changedFromAI!=='boolean') schemaErrors.push(id+': invalid material judgment');
  }
 }
 const material=arr.filter(d=>d?.reviewTier==='material_judgment').length;
 if(material!==25) schemaErrors.push('Expected 25 material judgments; found '+material);
 const unanswered=arr.filter(d=>!nonEmpty(d?.answer)||!nonEmpty(d?.finalAnswer)||isUnresolved(d)).map(d=>d?.id||'(missing ID)');
 const unmapped=[...new Set([...missing,...extra,...unanswered])];
 return {count:arr.length,dup,missing,extra,unmapped,schemaErrors,valid:arr.length===100&&!dup.length&&!unmapped.length&&!schemaErrors.length};
}
document.querySelector('#json-file').addEventListener('change',e=>{ const file=e.target.files[0]; if(!file)return; const reader=new FileReader(); reader.onload=()=>{try{const data=JSON.parse(reader.result);const validation=validate(data);pendingImport=validation.valid?{data,filename:file.name,validation}:null;importOutcome={filename:file.name,validation,applied:false};showToast(validation.valid?'Validation passed; review result and apply import':'Import rejected; saved data retained');}catch(err){pendingImport=null;importOutcome={filename:file.name,error:'Invalid JSON: '+err.message,applied:false};showToast('Import rejected; saved data retained');}e.target.value='';setPage('import');};reader.onerror=()=>{pendingImport=null;importOutcome={filename:file.name,error:'File could not be read',applied:false};e.target.value='';setPage('import');};reader.readAsText(file);});
function showToast(msg){toast.textContent=msg;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2600)}
document.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>setPage(b.dataset.page)));
const restored=REVIEW_MODE?false:hydrateImportedData();
if(restored){setPage('overview');updateSourceStatus();}
else { app.innerHTML='<div class="card">Loading the preliminary answer set…</div>'; updateSourceStatus(); fetch(REVIEW_MODE?'../submission.json':'DPI-HT-01_review_draft_for_import.json').then(r=>{if(!r.ok)throw Error('Source unavailable');return r.json()}).then(obj=>{if(!Array.isArray(obj.decisions))throw Error('Invalid source');dataset={...dataset,decisions:obj.decisions,imported:REVIEW_MODE,reviewable:validate(obj).valid,source:REVIEW_MODE?'submission.json':'preview JSON'};if(!REVIEW_MODE)restoreReviews();updateSourceStatus();setPage('overview')}).catch(()=>{app.innerHTML='<div class="card">The preliminary JSON could not be loaded. Reload the page or import a local copy.</div>'}); }

fetch('/submission.json').then(response=>{if(!response.ok)throw Error('Published submission unavailable');return response.json()}).then(obj=>{if(isPublishedCertified(obj)){publishedSubmission=obj;publishedCertification=obj.studentCertification;updateSourceStatus();render(currentPage);}}).catch(()=>{});
